    target = instance["target"]

    # A negative target can never be reached.
    if target < 0:
        return {"num_vars": 0, "clauses": [[]]}

    # Target zero is always reachable via the empty sub-list.
    if target == 0:
        return {"num_vars": 0, "clauses": []}

    total = sum(numbers)
    if total < target:
        return {"num_vars": 0, "clauses": [[]]}

